## 📱 Usage Patterns

### Infinite Scroll Gallery

```dart
class GalleryWidget extends StatefulWidget {
  @override
  State createState() => _GalleryWidgetState();
}

class _GalleryWidgetState extends State<GalleryWidget> {
  final List<FileWithFolder> _images = [];
  int _currentPage = 0;
  bool _loading = false;
  bool _hasMore = true;

  @override
  void initState() {
    super.initState();
    _loadNextPage();
  }

  Future<void> _loadNextPage() async {
    if (_loading || !_hasMore) return;

    setState(() => _loading = true);

    final result = await galleryService.getImages(
      page: _currentPage,
      pageSize: 50,
    );

    setState(() {
      _images.addAll(result.items);
      _hasMore = result.hasMore;
      _currentPage++;
      _loading = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    return GridView.builder(
      itemCount: _images.length + (_hasMore ? 1 : 0),
      gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: 3,
      ),
      itemBuilder: (context, index) {
        if (index == _images.length) {
          _loadNextPage();
          return CircularProgressIndicator();
        }

        final image = _images[index];
        return FutureBuilder<String?>(
          future: galleryService.getThumbnailPath(image.file.id, 'medium'),
          builder: (context, snapshot) {
            if (snapshot.hasData && snapshot.data != null) {
              return Image.file(File(snapshot.data!), fit: BoxFit.cover);
            }
            return Container(color: Colors.grey[300]);
          },
        );
      },
    );
  }
}
```

