class Animal {
    public void Eat() {
        Console.WriteLine("Eating...");
    }
}

class Dog : Animal {
    public void Bark() {
        Console.WriteLine("Barking...");
    }
}

Dog dog = new Dog();
dog.Eat();
dog.Bark();
```

### Interfaces

```csharp
interface IAnimal {
    void Speak();
}

class Cat : IAnimal {
    public void Speak() {
        Console.WriteLine("Meow");
    }
}

IAnimal cat = new Cat();
cat.Speak();
```

